/* CONFIG - qualified lead object -> clean CRM record + booking or human task. */
const CONFIG = {
  CRM_URL: $env.CRM_URL || "YOUR_CRM_OR_SUPABASE_URL",
  CRM_KEY: $env.CRM_KEY || "YOUR_SERVICE_KEY",
  CONTACTS_TABLE: "contacts", OPPS_TABLE: "opportunities",
  BOOKING_URL: "YOUR_BOOKING_URL",
  MIN_CONFIDENCE: 0.7
};
const H = this.helpers;
const HDRS = { apikey: CONFIG.CRM_KEY, Authorization: "Bearer " + CONFIG.CRM_KEY, "Content-Type": "application/json", Prefer: "return=representation" };
const j = $input.first().json;

// 1. Validate the structured lead schema (see docs - AI output must be validated
//    BEFORE it influences routing; deterministic safety codes override confidence)
const lead = j.lead || j;
const intentOk = ["request_service","schedule","existing_customer","urgent","unknown"].includes(lead.intent);
const conf = Number(lead.confidence);
const reasons = Array.isArray(lead.reasonCodes) ? lead.reasonCodes : [];
if (!intentOk || !lead.summary) return [{ json: { route: "human_task", reason: "invalid_schema", lead } }];
if (reasons.includes("SAFETY") || lead.urgency === "emergency_or_safety") {
  return [{ json: { route: "human_task", reason: "safety_override", lead } }];
}
if (!(conf >= CONFIG.MIN_CONFIDENCE) || lead.requiresHuman === true) {
  return [{ json: { route: "human_task", reason: "low_confidence", lead } }];
}

// 2. Normalize identifiers, SEARCH BEFORE CREATE
const phone = String(lead.phone || "").replace(/[^0-9+]/g, "");
const email = String(lead.email || "").toLowerCase().trim();
let contact = null, ambiguous = false;
try {
  const parts = [];
  if (phone) parts.push("phone.eq." + encodeURIComponent(phone));
  if (email) parts.push("email.eq." + encodeURIComponent(email));
  if (parts.length) {
    const found = await H.httpRequest({ url: CONFIG.CRM_URL + "/rest/v1/" + CONFIG.CONTACTS_TABLE + "?or=(" + parts.join(",") + ")&select=id,name,email,phone&limit=3", headers: HDRS, json: true });
    if (Array.isArray(found)) { if (found.length === 1) contact = found[0]; if (found.length > 1) ambiguous = true; }
  }
} catch (e) { return [{ json: { route: "human_task", reason: "crm_unavailable", error: String(e.message||e).slice(0,120), lead } }]; }
if (ambiguous) return [{ json: { route: "human_task", reason: "ambiguous_match", lead } }];

// 3. Create or update. NEVER overwrite authoritative fields with low-confidence AI text.
try {
  if (!contact) {
    const created = await H.httpRequest({ method: "POST", url: CONFIG.CRM_URL + "/rest/v1/" + CONFIG.CONTACTS_TABLE, headers: HDRS,
      body: { name: lead.name || "Unknown", phone, email, source: lead.source || "lead_recovery" }, json: true });
    contact = Array.isArray(created) ? created[0] : created;
  }
  // 4. Opportunity with summary + correlation
  await H.httpRequest({ method: "POST", url: CONFIG.CRM_URL + "/rest/v1/" + CONFIG.OPPS_TABLE, headers: HDRS,
    body: { contact_id: contact.id, service: lead.serviceCategory, urgency: lead.urgency,
            summary: lead.summary, status: "new", correlation_id: j.correlation || null }, json: true });
} catch (e) { return [{ json: { route: "human_task", reason: "crm_write_failed", error: String(e.message||e).slice(0,120), lead } }]; }

// 5. Booking vs human follow-up
const route = (lead.intent === "schedule" && lead.urgency !== "urgent") ? "booking" : "human_task";
return [{ json: { route, contact_id: contact.id, booking_url: CONFIG.BOOKING_URL,
  team_summary: "New qualified lead: " + (lead.name||"?") + " | " + (lead.serviceCategory||"?") + " | " + lead.urgency + "\n" + lead.summary } }];
